// Icon box is a `size`-keyed part (see `sizes` below), not a fixed value in baseStyle — lets
// ZimmButton's variant="social" path drive it via an iconSize prop (ZimmIconSize) for any
// future consumer that isn't the Apple/Google auth icons, while `md` (16px) stays the default,
// matching today's Figma-confirmed, no-responsive-variation behaviour with zero prop needed.
export const ZimmSocialButton = {
  parts: ['container', 'icon', 'label'],
  baseStyle: {
    // Inner flex row that centres icon + label together. The outer ChakraButton is the
    // shell (height, padding, border, hover/focus states); this container is the single
    // child the button's align-items:center vertically centres, so icon and label always
    // sit at the same baseline regardless of their individual heights.
    container: {
      display: 'flex',
      alignItems: 'center',
      justifyContent: 'center',
      gap: 'var(--zimm-scale-2xs)',
    },
    icon: {
      display: 'flex',
      alignItems: 'center',
      justifyContent: 'center',
      flexShrink: 0,
      // Chakra's createIcon (ZimmAppleSignInIcon/ZimmGoogleSignInIcon) renders the SVG at
      // 1em × 1em by default — font-relative, not a fixed pixel size. Without this, the icon
      // would silently scale with the button's own responsive font-size (12px mobile / 14px
      // desktop) instead of staying fixed at whatever box size is chosen below. Force it to
      // fill this span so the icon always scales to the box, never the font context.
      '& svg': { width: '100%', height: '100%' },
    },
    label: {
      // Figma: [text-box-trim:trim-both] [text-box-edge:cap_alphabetic]
      // text-box-trim strips the extra font-metric whitespace above the cap-height and below
      // the alphabetic baseline in Futura Round. Without it, uppercase text glyphs can appear
      // offset within their line-height box even when align-items:center is correct.
      flexShrink: 0,
      textBoxTrim: 'trim-both',
      textBoxEdge: 'cap alphabetic',
    },
  },
  sizes: {
    sm: { icon: { width: 'var(--zimm-icon-size-sm)', height: 'var(--zimm-icon-size-sm)' } },
    // Figma: size-[16px] at all breakpoints — no responsive variation. The default.
    md: { icon: { width: 'var(--zimm-icon-size-md)', height: 'var(--zimm-icon-size-md)' } },
    lg: { icon: { width: 'var(--zimm-icon-size-lg)', height: 'var(--zimm-icon-size-lg)' } },
    xl: { icon: { width: 'var(--zimm-icon-size-xl)', height: 'var(--zimm-icon-size-xl)' } },
  },
  defaultProps: {
    size: 'md',
  },
};

import React from 'react';
import { chakra, useMultiStyleConfig } from '@chakra-ui/react';
import { ZimmButton } from 'app/components/ui-kits/atoms/zimmButton';
import { ZimmAppleSignInIcon, ZimmGoogleSignInIcon } from 'app/components/icons';
import { useUiCopy } from 'app/hooks/useUiCopy';

const ZIMM_AUTH_DRAWER_CONTENT_RECIPE = 'ZimmAuthDrawerContent';

type SocialButtonsProps = {
  onSignInWithApple?: () => void;
  onSignInWithGoogle?: () => void;
};

export const SocialButtons = ({ onSignInWithApple, onSignInWithGoogle }: SocialButtonsProps) => {
  const { t } = useUiCopy();
  const signInWithApple = t('login.drawer.signInWithApple', 'Sign in with Apple');
  const signInWithGoogle = t('login.drawer.signInWithGoogle', 'Sign in with Google');
  const styles = useMultiStyleConfig(ZIMM_AUTH_DRAWER_CONTENT_RECIPE, {});

  return (
    <chakra.div __css={styles.socialStack}>
      {onSignInWithApple && (
        <ZimmButton
          variant="social"
          icon={<ZimmAppleSignInIcon />}
          label={signInWithApple}
          onClick={onSignInWithApple}
        />
      )}
      {onSignInWithGoogle && (
        <ZimmButton
          variant="social"
          icon={<ZimmGoogleSignInIcon />}
          label={signInWithGoogle}
          onClick={onSignInWithGoogle}
        />
      )}
    </chakra.div>
  );
};

import React from 'react';
import { chakra, useMultiStyleConfig } from '@chakra-ui/react';
import { Button as ChakraButton } from '@salesforce/retail-react-app/app/components/shared/ui';

const ZIMM_SOCIAL_BUTTON_RECIPE = 'ZimmSocialButton';

export type ZimmSocialButtonProps = {
  icon: React.ReactNode;
  label: string;
  onClick: () => void;
  isDisabled?: boolean;
};

/**
 * Full-width outlined button for social identity providers (Apple, Google).
 *
 * **Icon-and-label layout:** A `container` span (flex row, centred) holds an `aria-hidden`
 * icon span and a visible `label` span. Sizing and alignment for all three parts come from
 * ZimmSocialButton's own recipe (the `ZimmSocialButton` multi-part style config).
 * ChakraButton is used directly so the component fully owns its DOM structure without
 * depending on ZimmButton's iconLeading slot rendering.
 *
 * **Social button styling:** Root visual states (hover, press, focus, disabled) are delegated
 * to zimmButton.css.ts's `social` variant via `variant="social"` on ChakraButton, matching the
 * auth drawer Figma spec (secondary outline treatment with leading icon slot).
 */
export const ZimmSocialButton = ({ icon, label, onClick, isDisabled = false }: ZimmSocialButtonProps) => {
  // Explicit rather than relying on the recipe's defaultProps — this repo's multi-part recipes
  // are plain objects, not wrapped in Chakra's defineMultiStyleConfig, so defaultProps handling
  // isn't a verified guarantee here. 'md' matches the current, only-ever-used icon size.
  const styles = useMultiStyleConfig(ZIMM_SOCIAL_BUTTON_RECIPE, { size: 'md' });

  return (
    <ChakraButton
      type="button"
      variant="social"
      size="social"
      width="100%"
      isDisabled={isDisabled}
      onClick={onClick}
    >
      <chakra.span __css={styles.container}>
        <chakra.span aria-hidden={true} __css={styles.icon}>{icon}</chakra.span>
        <chakra.span __css={styles.label}>{label}</chakra.span>
      </chakra.span>
    </ChakraButton>
  );
};

