      // Audited 2026-09-16: 16px on both sides = 32px total, leaves ~343px on 375px mobile viewport
      // for accordion content — sufficient for label + checkbox.
      paddingInline: 'var(--zimm-scale-m)',
      paddingBlock: 'var(--zimm-scale-1200)',
      [`@media (min-width: ${breakpoints.md})`]: {
